#include <stdio.h>

enum GateState { LOCKED = 10, OPEN = 20 };

static const char *gate_label(int raw)
{
    switch (raw) {
    case LOCKED: return "locked";
    case OPEN: return "open";
    default: return "unknown";
    }
}

int main(void)
{
    puts(gate_label(10));
    puts(gate_label(20));
    puts(gate_label(0));
    return 0;
}

