#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

enum LoanState { REQUESTED = 1, ISSUED = 2, RETURNED = 3 };

static int known(int raw)
{
    return raw == REQUESTED || raw == ISSUED || raw == RETURNED;
}

static int can_move(enum LoanState from, enum LoanState to)
{
    /* TODO: name both permitted transitions. */
    return from == to;
}

int main(void)
{
    int value[2];
    const int minimum[] = {0, 0};
    const int maximum[] = {9, 9};
    if (!read_values(value, minimum, maximum, 2) ||
        !known(value[0]) || !known(value[1])) {
        puts("invalid");
        return 0;
    }
    enum LoanState from = (enum LoanState)value[0];
    enum LoanState to = (enum LoanState)value[1];
    puts(can_move(from, to) ? "ok" : "denied");
    return 0;
}

