enum LoanState { REQUESTED = 1, ISSUED = 2, RETURNED = 3 };

static int known(int raw)
{
    return raw == REQUESTED || raw == ISSUED || raw == RETURNED;
}

static int can_move(enum LoanState from, enum LoanState to)
{
    return (from == REQUESTED && to == ISSUED) ||
           (from == ISSUED && to == RETURNED);
}

int main(void)
{
    int value[2];
    const int minimum[] = {0, 0};
    const int maximum[] = {9, 9};
